	'trial_h' => 'Was ein Probemonat umfasst',
	'trial_p' => 'Ein Probemonat ist ein Standort und eine Matte: Installation, ein Tausch und ein klarer Weg, aufzuhören.',
	'trk_aria' => 'Die Vier-Wochen-Runde: In den Wochen 1 bis 3 bleibt die Matte liegen, in Woche 4 wird sie getauscht',
	'trk_swap' => 'Tausch',
